package com.okip.controller; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*; import com.okip.dto.preferences.EmployeePreferencesDTO; import com.okip.service.preferences.PreferencesService;
@RestController @RequestMapping("/api/preferences") public class PreferencesController{private final PreferencesService s; public PreferencesController(PreferencesService s){this.s=s;} @GetMapping public ResponseEntity<EmployeePreferencesDTO> get(){return ResponseEntity.ok(s.getMine());} @PutMapping public ResponseEntity<EmployeePreferencesDTO> update(@RequestBody EmployeePreferencesDTO d){return ResponseEntity.ok(s.update(d));}}
